TOPIC_RULES = [(r'response time|speed to lead|reply speed', 'tool:speed-to-lead-calculator/'),
               (r'no-show', 'tool:no-show-cost-calculator/'),
               (r'facebook|instagram|\bads\b|google ads|budget', 'chart'),
               (r'pricing|cost', 'tool:ai-receptionist-cost-calculator/'),
               (r'missed call|text back', 'tool:missed-call-calculator/'),
               (r'receptionist|answering|phone', 'tool:../demo/'),
               (r'onboarding|intake|automation', 'calc'),
               (r'follow-up|lead', 'spark'),
               (r'patients|chiropract|marketing', 'calendar')]

def topic_icon(text):
    """3D icon for a guide card, chosen by keywords in its label and title. Gradient ids get a per-icon prefix
    so different icons on one page never share an id."""
    t = text.lower()
    key = next((k for pat, k in TOPIC_RULES if re.search(pat, t)), 'chat')
    svg = ICONS[key[5:]] if key.startswith('tool:') else TOPIC_ICONS[key]
    pre = 'g' + re.sub(r'[^a-z]', '', key)[:10]
    for i in set(re.findall(r'id="([^"]+)"', svg)):
        svg = svg.replace(f'id="{i}"', f'id="{pre}{i}"').replace(f'url(#{i})', f'url(#{pre}{i})').replace(f'href="#{i}"', f'href="#{pre}{i}"')
    return svg
